 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");java.util.Set<String> ids=new java.util.TreeSet<>(ModBlocks.DISPLAY_SCREEN_IDS);ids.addAll(java.util.Arrays.asList(TileEntityAnimatedScreenSelector.INPUT_PANELS));ids.addAll(java.util.Arrays.asList("engineering_screen","foo_framed_bar","framed_unknown","future_saved"));int cases=0;
  for(String id:ids)for(String field:new String[]{"selectedScreen","inputPanel","secondaryInputPanel"})for(int front=0;front<3;front++){NBTTagCompound tag=new NBTTagCompound();tag.setString(field,id);tag.setString("Foreign","retained");if(front==1)tag.setInteger("FrameFront",-1);if(front==2)tag.setString("FrameFront","future");boolean needed=FrameAppearance.needsLegacyScreen(tag),changed=FrameAppearance.migrateLegacyScreen(tag);hash.update((needed+":"+changed+":"+canonical(tag)).getBytes("UTF-8"));cases++;}
  for(int choice=-4;choice<ScreenHousingTextures.BUILTIN_COUNT;choice++)for(String field:new String[]{"PrimarySurfaceTexture","SecondarySurfaceTexture"}){NBTTagCompound tag=new NBTTagCompound();tag.setInteger(field,choice);boolean needed=FrameAppearance.needsLegacyScreen(tag),changed=FrameAppearance.migrateLegacyScreen(tag);hash.update((needed+":"+changed+":"+canonical(tag)).getBytes("UTF-8"));cases++;}
  StringBuilder out=new StringBuilder();for(byte b:hash.digest())out.append(String.format("%02x",b&255));if(!out.toString().equals("94527eaa6d795c6fe784c5d5c639a8506aec23b336488332d1ecf2b966f09d49"))throw new AssertionError("Actual artwork migration changed "+out);com.google.gson.JsonObject catalog=new com.google.gson.JsonObject();catalog.add("ids",new com.google.gson.Gson().toJsonTree(ids));catalog.add("screens",new com.google.gson.Gson().toJsonTree(ModBlocks.DISPLAY_SCREEN_IDS));catalog.add("options",new com.google.gson.Gson().toJsonTree(ModBlocks.SCREEN_OPTIONS));catalog.addProperty("defaultHousing",ScreenHousingTextures.screenIndex("door_inner"));for(String name:new String[]{"SCREEN_REDIRECTS","INPUT_REDIRECTS"}){java.lang.reflect.Field field=ScreenHousingTextures.class.getDeclaredField(name);field.setAccessible(true);catalog.add(name.equals("SCREEN_REDIRECTS")?"screenAliases":"inputAliases",new com.google.gson.Gson().toJsonTree(field.get(null)));}com.google.gson.JsonObject sourceChoices=new com.google.gson.JsonObject(),frameCounts=new com.google.gson.JsonObject();for(int i=0;i<com.vandorlabs.tiles.HousingFinishCatalog.legacyCount();i++)for(String name:new String[]{com.vandorlabs.tiles.HousingFinishCatalog.id(i),com.vandorlabs.tiles.HousingFinishCatalog.texture(i)})sourceChoices.addProperty(name,ScreenHousingTextures.clamp(ScreenHousingTextures.screenIndex(name)));for(int i=com.vandorlabs.tiles.HousingFinishCatalog.legacyCount();i<ScreenHousingTextures.BUILTIN_COUNT;i++){String name=ScreenHousingTextures.entry(i).get("source").getAsString();sourceChoices.addProperty(name,ScreenHousingTextures.clamp(ScreenHousingTextures.screenIndex(name)));}for(String name:TileEntityAnimatedScreenSelector.INPUT_PANELS)frameCounts.addProperty(name,TileEntityAnimatedScreenSelector.getInputFrameCount(name));catalog.add("sources",sourceChoices);catalog.add("inputFrames",frameCounts);catalog.add("inputs",new com.google.gson.Gson().toJsonTree(TileEntityAnimatedScreenSelector.INPUT_PANELS));catalog.add("framed",new com.google.gson.Gson().toJsonTree(new java.util.TreeSet<String>(ModBlocks.DISPLAY_FRAMED_IDS)));com.google.gson.JsonObject pairs=new com.google.gson.JsonObject();for(ModBlocks.ScreenOption option:ModBlocks.SCREEN_OPTIONS)if(option.hasPair())pairs.addProperty(option.framedId,option.bareId);catalog.add("pairs",pairs);catalog.addProperty("frame",ScreenHousingTextures.screenIndex("frames/frames-screen-full/frame_bolted_1254"));com.google.gson.JsonArray choices=new com.google.gson.JsonArray();for(int choice=0;choice<ScreenHousingTextures.BUILTIN_COUNT;choice++){NBTTagCompound probe=new NBTTagCompound();probe.setInteger("PrimarySurfaceTexture",choice);com.google.gson.JsonObject entry=new com.google.gson.JsonObject();entry.addProperty("framed",FrameAppearance.needsLegacyScreen(probe));entry.addProperty("bare",FrameAppearance.bareChoice(choice));choices.add(entry);}catalog.add("choices",choices);java.nio.file.Path output=java.nio.file.Paths.get(System.getProperty("screenArtworkReference","build/test-artifacts/screen-artwork-reference.json"));java.nio.file.Files.createDirectories(output.toAbsolutePath().getParent());java.nio.file.Files.write(output,new com.google.gson.Gson().toJson(catalog).getBytes("UTF-8"));System.out.println("Actual Screen artwork migration reference PASS cases="+cases+" sha256="+out);}
 private static String canonical(NBTTagCompound tag){StringBuilder out=new StringBuilder("{");for(String key:new java.util.TreeSet<String>(tag.getKeySet()))out.append(key).append(':').append(tag.getTag(key)).append(';');return out.append('}').toString();}
